import{_ as a,o,c as r,ab as n}from"./chunks/framework.DfnUYNhO.js";const m=JSON.parse('{"title":"Preparar colaboración y acceso de equipos","description":"","frontmatter":{"title":"Preparar colaboración y acceso de equipos","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"2fbcef6dfd6d359e74bc4db46dcadc42e42a4b172f42bc0b10c7ec9475ff747b","order":30},"headers":[],"relativePath":"es/user/cloud/collaboration.md","filePath":"es/user/cloud/collaboration.md","lastUpdated":1795476229000}'),t={name:"es/user/cloud/collaboration.md"};function i(c,e,s,l,d,p){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Preparar colaboración y acceso de equipos <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Preparar colaboración y acceso de equipos {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Asigna a otro operador un papel definido manteniendo el control del propietario. El acceso remoto lo ofrece el plugin instalable <strong>Remote Control</strong>, no una pestaña de ajustes: necesitas <a href="./account.html">sesión de Cloud</a>, un backend compatible y el plugin instalado en este host. Comienza con acceso de lectura en un entorno de prueba.</p><h2 id="configure-remote-access" tabindex="-1">Configurar el acceso remoto <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to &quot;Configurar el acceso remoto {#configure-remote-access}&quot;">​</a></h2><ol><li>Instala y habilita <code>tiktools.remote-control</code> y abre su página <strong>Remote control</strong>.</li><li>Crea un equipo y registra <strong>este PC</strong> como host con una etiqueta de dispositivo reconocible; inicia el enlace de retransmisión y espera a que su estado sea <code>ready</code>.</li><li>Crea una invitación y entrega su token de un solo uso por un canal confiable. Una invitación no es una sesión activa aprobada.</li><li>Revisa la solicitud pendiente y el papel solicitado. Aprueba solo al operador esperado; la concesión permanece <code>pendingHost</code> hasta que el enlace del host la confirma.</li><li>Revisa periódicamente las concesiones y los dispositivos. Revoca una concesión cuando deje de ser necesaria.</li></ol><p>Editar una definición delegada, adoptarla como propietario y aprobar su ejecución son decisiones distintas. Lee el código guardado, las acciones referenciadas y los permisos en la revisión específica. Una vista previa por sí sola no autoriza efectos.</p><h2 id="prepare-a-controller-device" tabindex="-1">Preparar un dispositivo controlador <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to &quot;Preparar un dispositivo controlador {#prepare-a-controller-device}&quot;">​</a></h2><p>En el dispositivo controlador, inicia sesión con su propia cuenta, regístralo como controlador y canjea el token de invitación. El propietario verá entonces una solicitud pendiente. La búsqueda por apodo requiere un endpoint de backend desplegado por separado y puede no estar disponible en el servicio actual. Un fallo de búsqueda no demuestra que la persona carezca de cuenta; tampoco sustituyas la selección por un ID arbitrario.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El flujo entre dos cuentas (equipo, enlace del host, invitación, aprobación, comando de lectura y revocación) se ha verificado con un backend local. Las pestañas de colaboración/equipos en ajustes fueron eliminadas; el servicio nativo de colaboración no tiene interfaz web en esta versión. El comportamiento de retransmisión/NAT en producción, la búsqueda por apodo y la operación LIVE entre dos PC no están aquí comprobados. Un enlace listo no demuestra por sí solo el funcionamiento íntegro de los permisos para tu acción.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Para concesiones obsoletas, revoca el acceso y revísalo de nuevo tras la actualización del enlace. Ante comandos sin confirmar, inspecciona el resultado registrado antes de repetir. Detén el enlace o revoca el acceso al terminar la sesión. Mantén tokens de invitación y credenciales fuera de los <a href="./../preferences/troubleshooting.html">informes públicos</a>.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Cada comando remoto pasa por la compuerta de capacidades del host (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>); el plugin nunca recibe una Control API ni un token completo. Un transporte activo o la pertenencia a un equipo no conceden acceso nativo por sí solos. Observer orienta a lectura; moderator añade controles concretos, automationEditor edición concreta y custom requiere una política explícita revisada. Ninguno concede scripts/efectos ilimitados. Consulta <a href="./../../developer/collaboration.html#operational-details">roles y confirmación</a> y <a href="./../../developer/transports.html">transports</a> para conocer el límite actual.</p>',14)])])}const b=a(t,[["render",i]]);export{m as __pageData,b as default};
